<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Search,Refresh,FullScreen} from '@element-plus/icons-vue'
import {usePageGuide} from '../spec/guide-context'
import type {GuideTopic} from '../spec/types'
import {clone,newActivity,activityStatus,activityOrder,rewardSummary,roleLabels,activityRoles,voucherBenefit,type Activity,type ActivityReward,type Config,type Store} from '../model'
const props=defineProps<{config:Config;store:Store;readonly:boolean;busy:boolean;fullscreen:boolean;now:number;saveActivity:(activity:Activity)=>Promise<string>;deleteActivity:(id:string)=>Promise<string>}>()
const emit=defineEmits<{refresh:[];fullscreen:[]}>()
const filters=reactive({query:'',status:'',reward:''}),applied=ref({...filters}),page=ref(1),size=ref(20),showSearch=ref(true)
const filtered=computed(()=>props.config.activities.filter(a=>!a.archived&&(!applied.value.query||(a.id+a.name).includes(applied.value.query))&&(!applied.value.status||activityStatus(a,props.now)===applied.value.status)&&(!applied.value.reward||a.rewards.some(r=>r.enabled&&r.kind===applied.value.reward))).sort(activityOrder))
const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value)),roles=activityRoles
const open=ref(false),mode=ref<'create'|'edit'|'view'>('create'),activity=ref<Activity>(newActivity()),error=ref(''),generation=ref(0),submitting=ref(false)
const selectedKinds=computed({get:()=>activity.value.rewards.filter(r=>r.enabled).map(r=>r.kind),set:(kinds:ActivityReward['kind'][])=>{for(const kind of ['member','voucher'] as const){let reward=activity.value.rewards.find(r=>r.kind===kind);if(!reward){reward=kind==='member'?{kind,enabled:false,target:10,months:1,repeat:true,perUserLimit:0}:{kind,enabled:false,target:1,templateId:props.config.vouchers.templates.find(t=>t.enabled)?.id??'',quantity:1,repeat:true,perUserLimit:0};activity.value.rewards.push(reward)}reward.enabled=kinds.includes(kind)}}})
const activeRewards=computed(()=>activity.value.rewards.filter(r=>r.enabled)),isView=computed(()=>mode.value==='view'||props.readonly)
const confirmationTopic=ref<GuideTopic|null>(null)
usePageGuide(()=>confirmationTopic.value?{topic:confirmationTopic.value,priority:40}:open.value?{topic:isView.value?'activity_view':mode.value==='create'?'activity_create':'activity_edit',priority:20,detail:'当前'+(isView.value?'只读详情':'编辑副本')+'；时间：'+(activity.value.period==='permanent'?'长期有效':'指定时间')+'；奖励：'+(activeRewards.value.map(r=>r.kind==='member'?'会员':'优惠券').join('＋')||'尚未选择')}:null)
const participants=(id:string)=>props.store.invites.filter(i=>i.activityResults?.some(r=>r.activityId===id&&r.status==='已计数')).length
const grantCount=(id:string)=>props.store.grants.filter(g=>g.activityId===id).length
const hasRecords=(id:string)=>props.store.invites.some(i=>i.activityResults?.some(r=>r.activityId===id&&r.status!=='未命中'&&r.status!=='优先级排除'))||props.store.grants.some(g=>g.activityId===id)||Object.entries(props.store.progress).some(([key,p])=>key.includes(':'+id+':')&&p.count>0)
function search(){applied.value={...filters};page.value=1}
function reset(){Object.assign(filters,{query:'',status:'',reward:''});search()}
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/size.value)))})
function show(value:Activity|null,view=false,copy=false){generation.value++;activity.value=value?clone(value):newActivity();if(copy){activity.value.id='ACT-'+Date.now();activity.value.name=activity.value.name.slice(0,34)+'（副本）';activity.value.enabled=false;activity.value.archived=false}mode.value=view?'view':value&&!copy?'edit':'create';error.value='';open.value=true}
async function save(){if(props.readonly||submitting.value||props.busy)return;submitting.value=true;try{const previous=props.config.activities.find(a=>a.id===activity.value.id);if(previous?.enabled&&(!activity.value.enabled||previous.rewards.some(r=>r.enabled&&!activity.value.rewards.some(n=>n.kind===r.kind&&n.enabled)))){confirmationTopic.value='activity_reward_confirm';await ElMessageBox.confirm('停用或取消奖励后，后续邀请不再累计对应进度。历史资产、未完成轮次及已达标待发单保留。','确认调整活动奖励',{type:'warning',confirmButtonText:'确认保存',cancelButtonText:'取消'});confirmationTopic.value=null}error.value=await props.saveActivity(clone(activity.value));if(error.value)ElMessage.error(error.value);else open.value=false}catch{/* Cancel leaves the form intact. */}finally{submitting.value=false;confirmationTopic.value=null}}
async function toggle(a:Activity){if(props.readonly||props.busy)return;try{if(a.enabled){confirmationTopic.value='activity_toggle';await ElMessageBox.confirm('停用后不再接收新的活动进度；历史奖励和待发单保留，恢复后延续原进度。','停用「'+a.name+'」',{type:'warning',confirmButtonText:'确认停用',cancelButtonText:'取消'});confirmationTopic.value=null}const next=clone(a);next.enabled=!next.enabled;const message=await props.saveActivity(next);if(message)ElMessage.error(message)}catch{}finally{confirmationTopic.value=null}}
async function remove(a:Activity){if(props.readonly||props.busy||a.enabled||hasRecords(a.id))return;try{confirmationTopic.value='activity_remove';await ElMessageBox.confirm('仅可删除已停用且没有参与记录、奖励或未完成进度的活动。删除后从活动列表移除，数据保留。','删除「'+a.name+'」',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});const message=await props.deleteActivity(a.id);if(message)ElMessage.error(message)}catch{}finally{confirmationTopic.value=null}}
const template=(id:string)=>props.config.vouchers.templates.find(t=>t.id===id)
</script>
<template>
 <section v-if="showSearch" class="search-card"><el-form label-width="82px" @submit.prevent="search"><div class="query-grid"><el-form-item label="活动名称"><el-input v-model="filters.query" placeholder="活动名称 / 编号" clearable @keyup.enter="search"/></el-form-item><el-form-item label="活动状态"><el-select v-model="filters.status" placeholder="全部状态" clearable><el-option v-for="s in ['进行中','未开始','已结束','已停用']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="奖励类型"><el-select v-model="filters.reward" placeholder="全部奖励" clearable><el-option value="member" label="会员"/><el-option value="voucher" label="优惠券"/></el-select></el-form-item><div class="search-actions"><el-button @click="reset">重置</el-button><el-button type="primary" @click="search">搜索</el-button></div></div></el-form></section>
 <div class="primary-actions"><el-button type="primary" :icon="Plus" :disabled="readonly" @click="show(null)">新增活动</el-button></div>
 <section class="list-card"><div class="list-header"><strong>活动列表</strong><el-space :size="8"><el-tooltip content="显示 / 隐藏搜索"><el-button circle :icon="Search" aria-label="显示搜索" :type="showSearch?'primary':'default'" @click="showSearch=!showSearch"/></el-tooltip><el-tooltip content="刷新列表"><el-button circle :icon="Refresh" aria-label="刷新列表" @click="emit('refresh')"/></el-tooltip><el-tooltip :content="fullscreen?'退出全屏':'全屏工作区'"><el-button circle :icon="FullScreen" :aria-label="fullscreen?'退出全屏':'全屏工作区'" @click="emit('fullscreen')"/></el-tooltip></el-space></div>
 <el-table :data="rows" row-key="id" border class="configuration-table" empty-text="暂无匹配活动，可调整筛选或新增活动"><el-table-column prop="id" label="活动编号" min-width="150" show-overflow-tooltip/><el-table-column label="活动名称" min-width="160" show-overflow-tooltip><template #default="{row}"><el-button type="primary" link @click="show(row,true)">{{row.name}}</el-button><div class="subline">邀请注册</div></template></el-table-column><el-table-column label="奖励与达标条件" min-width="260"><template #default="{row}"><div v-for="r in row.rewards.filter((r:ActivityReward)=>r.enabled)" :key="r.kind">{{rewardSummary(r,config,true)}}</div></template></el-table-column><el-table-column label="活动时间" min-width="140"><template #default="{row}"><span v-if="row.period==='permanent'">长期有效</span><template v-else>{{row.start}}<div class="subline">至 {{row.end}}</div></template></template></el-table-column><el-table-column label="状态" width="85" align="center"><template #default="{row}"><el-tag :type="activityStatus(row,now)==='进行中'?'success':activityStatus(row,now)==='未开始'?'warning':'info'">{{activityStatus(row,now)}}</el-tag></template></el-table-column><el-table-column label="操作" width="210" fixed="right" align="center"><template #default="{row}"><el-button type="primary" link @click="show(row,true)">详情</el-button><el-button v-if="!readonly" type="primary" link @click="show(row)">编辑</el-button><el-button v-if="!readonly" type="primary" link @click="show(row,false,true)">复制</el-button><el-button v-if="!readonly" :type="row.enabled?'warning':'primary'" link :disabled="busy" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button><el-tooltip v-if="!readonly" :content="row.enabled?'请先停用活动':hasRecords(row.id)?'已有参与记录、奖励或进度，请停用保留追溯':'删除无记录活动'"><span class="inline-button"><el-button type="danger" link :disabled="row.enabled||hasRecords(row.id)||busy" @click="remove(row)">删除</el-button></span></el-tooltip></template></el-table-column></el-table>
 <div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50]" :total="filtered.length" layout="total, sizes, prev, pager, next" @size-change="page=1"/></div></section>
 <el-drawer v-model="open" :title="isView?'活动详情':mode==='create'?'新增活动':'编辑活动'" size="min(1060px, calc(100vw - 72px))" :close-on-click-modal="true">
 <template v-if="isView"><el-descriptions :column="2" border><el-descriptions-item label="活动名称">{{activity.name}}</el-descriptions-item><el-descriptions-item label="活动编号">{{activity.id}}</el-descriptions-item><el-descriptions-item label="状态">{{activityStatus(activity)}}</el-descriptions-item><el-descriptions-item label="活动时间" :span="2">{{activity.period==='permanent'?'长期有效':activity.start+' 至 '+activity.end}}</el-descriptions-item><el-descriptions-item label="邀请人身份">{{activity.inviterRoles.map(r=>roleLabels[r]).join('、')}}</el-descriptions-item><el-descriptions-item label="新用户身份">{{activity.inviteeRoles.map(r=>roleLabels[r]).join('、')}}</el-descriptions-item><el-descriptions-item label="完成条件" :span="2">邀请新用户首次完成注册，同一实际用户只计一次</el-descriptions-item><el-descriptions-item label="异常邀请">{{activity.riskPolicy==='hold'?'待核验后计奖':'拒绝计奖并留痕'}}</el-descriptions-item><el-descriptions-item label="有效参与事件">{{participants(activity.id)}}条</el-descriptions-item><el-descriptions-item label="奖励发放单">{{grantCount(activity.id)}}笔（含待处理）</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{activity.note||'—'}}</el-descriptions-item></el-descriptions><h3 class="section-title">奖励配置</h3><el-table :data="activeRewards" border><el-table-column label="奖励类型" width="110"><template #default="{row}">{{row.kind==='member'?'会员':'优惠券'}}</template></el-table-column><el-table-column label="达标条件与奖励" min-width="300"><template #default="{row}">{{rewardSummary(row,config)}}</template></el-table-column><el-table-column label="每人累计上限" min-width="140"><template #default="{row}">{{!row.repeat?'仅一次':row.perUserLimit?row.perUserLimit+(row.kind==='member'?'次':'张'):'不限'}}</template></el-table-column></el-table></template>
 <el-form v-else :key="generation" :disabled="readonly||busy||submitting" label-width="138px" class="configuration-form activity-form">
 <section class="panel"><div class="panel-heading"><h2>活动信息</h2></div><div class="form-body"><el-row :gutter="24"><el-col :span="12"><el-form-item label="活动名称" required><el-input v-model="activity.name" maxlength="40" show-word-limit placeholder="例如：邀请好友双重奖励"/></el-form-item></el-col><el-col :span="12"><el-form-item label="活动编号"><el-input :model-value="activity.id" disabled/></el-form-item></el-col></el-row><el-form-item label="活动开关"><el-switch v-model="activity.enabled" active-text="启用" inactive-text="停用"/></el-form-item><el-form-item label="活动时间" required><el-radio-group v-model="activity.period"><el-radio value="permanent">长期有效</el-radio><el-radio value="range">指定时间</el-radio></el-radio-group></el-form-item><el-form-item v-if="activity.period==='range'" label="起止时间" required><el-date-picker v-model="activity.start" aria-label="活动开始时间" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="开始时间"/><span class="unit">至</span><el-date-picker v-model="activity.end" aria-label="活动结束时间" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="结束时间"/><p class="field-hint">北京时间，包含开始时刻，不包含结束时刻。</p></el-form-item></div></section>
 <section class="panel"><div class="panel-heading"><h2>参与与完成条件</h2></div><div class="form-body"><el-form-item label="完成条件" required><el-select v-model="activity.trigger"><el-option value="invite-register" label="邀请新用户首次完成注册"/></el-select></el-form-item><el-form-item label="邀请人身份" required><el-checkbox-group v-model="activity.inviterRoles"><el-checkbox v-for="r in roles" :key="r" :value="r">{{roleLabels[r]}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="新用户身份" required><el-checkbox-group v-model="activity.inviteeRoles"><el-checkbox v-for="r in roles" :key="r" :value="r">{{roleLabels[r]}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="异常邀请处理"><el-radio-group v-model="activity.riskPolicy"><el-radio value="hold">待核验，不加进度不发奖</el-radio><el-radio value="block">拒绝计奖，保留原因</el-radio></el-radio-group></el-form-item></div></section>
 <section class="panel"><div class="panel-heading"><h2>赠送奖励与达标条件</h2></div><div class="form-body"><el-form-item label="赠送什么" required><el-checkbox-group v-model="selectedKinds"><el-checkbox value="member">会员</el-checkbox><el-checkbox value="voucher">优惠券</el-checkbox></el-checkbox-group></el-form-item><div v-for="r in activeRewards" :key="r.kind" class="activity-reward-block"><h3>{{r.kind==='member'?'赠送会员':'赠送优惠券'}}</h3><el-row :gutter="24"><el-col :span="12"><el-form-item label="累计邀请人数" required><el-input-number v-model="r.target" :aria-label="r.kind==='member'?'会员达标人数':'优惠券达标人数'" :min="1" :max="100000" :precision="0"/><span class="unit">人 / 轮</span></el-form-item></el-col><el-col :span="12"><el-form-item v-if="r.kind==='member'" label="每轮赠送时长" required><el-input-number v-model="r.months" :min="1" :max="120" :precision="0"/><span class="unit">个自然月</span></el-form-item><el-form-item v-else label="每轮赠送张数" required><el-input-number v-model="r.quantity" :min="1" :max="100" :precision="0"/><span class="unit">张</span></el-form-item></el-col></el-row><template v-if="r.kind==='voucher'"><el-form-item label="优惠券模板" required><el-select v-model="r.templateId" placeholder="选择优惠券配置中已启用的模板"><el-option v-for="t in config.vouchers.templates" :key="t.id" :value="t.id" :label="t.name+' · '+voucherBenefit(t)+(t.enabled?'':'（已停用）')" :disabled="!t.enabled"/></el-select><p v-if="!template(r.templateId)?.enabled" class="field-hint error-text">启用活动前，请先启用关联券模板。</p></el-form-item></template><el-form-item label="重复达标奖励"><el-switch v-model="r.repeat" :aria-label="r.kind==='member'?'会员重复奖励':'优惠券重复奖励'" active-text="每达标一轮发一次" inactive-text="每人仅奖励一轮"/></el-form-item><el-form-item v-if="r.repeat" label="每人累计上限"><el-input-number v-model="r.perUserLimit" :aria-label="r.kind==='member'?'会员累计奖励上限':'优惠券累计奖励上限'" :min="0" :max="1000000" :precision="0"/><span class="unit">{{r.kind==='member'?'次':'张'}}，0 表示不限</span></el-form-item></div></div></section><section class="panel"><div class="form-body compact"><el-form-item label="活动备注"><el-input v-model="activity.note" type="textarea" :rows="2" maxlength="200" show-word-limit placeholder="仅供后台查看"/></el-form-item></div></section></el-form>
 <el-alert v-if="error" :title="error" type="error" :closable="false" class="mt16"/><template #footer><el-button :disabled="busy||submitting" @click="open=false">{{isView?'关闭':'取消'}}</el-button><el-button v-if="isView&&!readonly" type="primary" @click="show(activity)">编辑活动</el-button><el-button v-if="!isView" type="primary" :loading="busy||submitting" @click="save">保存</el-button></template></el-drawer>
</template>
